impl Solution{pub fn get_max_grid_happiness(mut m:i32,mut n:i32,introverts_count:i32,extroverts_count:i32)->i32{let ic=introverts_count;let ec=extroverts_count;if n>m{std::mem::swap(&mut m,&mut n)};let k=3usize.pow(n as u32);let mut h=vec![0;k];let mut a=vec![0;k];let mut b=vec![0;k];for x in 0..k{let(mut q,mut p)=(x,0);for _ in 0..n{let d=q%3;q/=3;if d==1{h[x]+=120;a[x]+=1}else if d==2{h[x]+=40;b[x]+=1}if d>0&&p>0{h[x]+=if d==1{-30}else{20};h[x]+=if p==1{-30}else{20}};p=d}}fn f(r:i32,m:i32,n:i32,i:i32,e:i32,p:usize,h:&Vec<i32>,a:&Vec<i32>,b:&Vec<i32>,z:&mut HashMap<(i32,i32,i32,usize),i32>)->i32{if r==m{return 0}if let Some(v)=z.get(&(r,i,e,p)){return *v}let mut best=0;for c in 0..h.len(){if a[c]<=i&&b[c]<=e{let(mut x,mut y,mut s)=(p,c,0);for _ in 0..n{let u=x%3;let d=y%3;x/=3;y/=3;if u>0&&d>0{s+=if u==1{-30}else{20};s+=if d==1{-30}else{20}}}best=best.max(h[c]+s+f(r+1,m,n,i-a[c],e-b[c],c,h,a,b,z));}}z.insert((r,i,e,p),best);best}f(0,m,n,ic,ec,0,&h,&a,&b,&mut HashMap::new())}}
